// K6 transcript, edge harness: the production bundle (router_core.js) — AgentMoneyPlans (60) + IouLog (105) —
// running C13 / C135 / C181 end to end on the sandbox P2P rail. The same conversations are saved word-for-word
// at ~/workspace/your_files/upmore-conversations/C13-*.md, C135-*.md, C181-*.md (generated by
// tests/k6-proof.cjs from these exact outputs). Real Venmo/Zelle are NOT_WIRED; the sandbox is labeled sandbox.
import { AgentMoneyPlans, IouLog } from "../../supabase/functions/_shared/router_core.js";

const eq = (a: unknown, b: unknown, m?: string) => { if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(`${m ?? "not equal"}:\n  ${JSON.stringify(a)}\n  ${JSON.stringify(b)}`); };
const MP = AgentMoneyPlans as any, IOU = IouLog as any;
const people = [
  { id: "p1", name: "Sarah M", handle: "@sarah-m", rails: ["venmo"], history: [{ amount_cents: 8500, on: "2026-09-01" }] },
  { id: "p5", name: "Maya", handle: "@maya", rails: ["cash_app"], history: [] },
  { id: "p6", name: "Priya N", handle: "@priya-n", rails: [], history: [] },
];
const DINNER = { id: "tx-dinner", account_id: "chk", posted_at: "2026-10-08", posted_on: "2026-10-08", amount_cents: -9600, merchant_raw: "SQ *ALLEY CAT CAFE", is_pending: false, is_transfer: false };
const ledger = () => MP.fromTaggedTransaction(DINNER, { shared_with: ["Sarah M", "Maya"], paid_by: "me", what: "Alley Cat Cafe dinner" }).entries
  .concat([{ id: "iou-taxi-priya", name: "Priya N", direction: "owes_me", amount_cents: 1500, original_cents: 1500, note: "taxi", created_on: "2026-10-09", status: "open", transaction_id: "tx-taxi" }]);

Deno.test("K6 C135 transcript: collect-all on the sandbox rail, a paid claim closes nothing, reminders escalate, only a posted receipt settles", () => {
  const rail = MP.sandboxRail(), ious = ledger();
  const col = MP.collectAll(ious, { people, today: "2026-10-10", sandbox_rail: rail });
  eq(col.text, [
    "Collecting $79.00 from 3 people:",
    "Sarah M: $32.00 for Alley Cat Cafe dinner on Venmo — sandbox ref sbx-1, delivery verified in the sandbox outbox.",
    "Maya: $32.00 for Alley Cat Cafe dinner on Cash App — sandbox ref sbx-2, delivery verified in the sandbox outbox.",
    "Priya N: $15.00 for taxi — no request rail on file (NOT_WIRED), draft only.",
    "Real rails are NOT_WIRED: Venmo and Zelle have no consumer API, so nothing was sent on a real rail. These requests went out only on the sandbox P2P rail (labeled sandbox), and each one closes only when its payment posts.",
    "Reminders follow on a schedule while a request stays open; a debt closes only when the payment actually posts.",
  ].join("\n"));
  eq(MP.notePaidClaim(ious, col.requests, "Sarah M").text, "Noted: Sarah M says they paid the $32.00. That doesn't close it — a debt closes only when the payment posts. It's still open at $32.00 and I'll keep watching for the receipt.");
  eq(IOU.command("sarah m paid me back", ious, Date.parse("2026-10-12T15:00:00Z")).reply, "That one is receipt-tracked: the $32.00 Sarah M owes you (Alley Cat Cafe dinner) came from a real charge, so it clears only when the matching payment posts to your account. A say-so doesn't clear it, and I haven't seen that payment yet. Nothing changed.");
  const sarah = col.requests[0];
  eq(MP.dueReminders([sarah], "2026-10-17")[0].text, "Hey Sarah, when you get a sec: $32.00 for Alley Cat Cafe dinner. No rush!");
  eq(MP.dueReminders([sarah], "2026-10-24")[0].text, "Second reminder: $32.00 for Alley Cat Cafe dinner.");
  eq(MP.dueReminders([sarah], "2026-10-27")[0].text, "Final reminder: $32.00 for Alley Cat Cafe dinner, 17 days outstanding.");
  rail.postReceipt({ from_name: "Maya", from_handle: "@maya", amount_cents: 3200, on: "2026-10-19" });
  const out = MP.settleIous(ious, col.requests, rail.feed(), people);
  eq(out.settled[0].text, "Maya paid the $32.00 for Alley Cat Cafe dinner on 2026-10-19.");
  eq(out.ious.find((e: any) => e.name === "Sarah M").status, "open");
});

Deno.test("K6 C181 transcript: Netflix Premium shares to the cent, receipts tracked month to month", () => {
  const household = [
    { id: "a1", name: "Asha", handle: "@asha", rails: ["venmo"], history: [] },
    { id: "a2", name: "Ravi", handle: "@ravi", rails: ["zelle"], history: [] },
    { id: "a3", name: "Meera", handle: "@meera", rails: ["venmo"], history: [] },
  ];
  const spec = (month: string, on: string) => ({ service: "Netflix", plan_label: "Netflix Premium", month, members: ["Asha", "Ravi", "Meera"], charge: { id: `tx-nfx-${month}`, amount_cents: 2299, posted_on: on, merchant_raw: "NETFLIX.COM" } });
  const oct = MP.subscriptionShares(spec("2026-10", "2026-10-03"), { people: household, today: "2026-10-03" });
  eq(oct.text, "Netflix Premium is $22.99 for 2026-10, split 4 ways (you $5.75, Asha $5.75, Ravi $5.75, Meera $5.74). Cost-share requests: Asha $5.75, Ravi $5.75, Meera $5.74. Each closes only when that member's payment posts.");
  const rail = MP.sandboxRail();
  rail.postReceipt({ from_name: "Asha", from_handle: "@asha", amount_cents: 575, on: "2026-10-05" });
  const nov = MP.subscriptionShares(spec("2026-11", "2026-11-03"), { people: household, today: "2026-11-03" });
  const out = MP.settleIous(oct.entries.concat(nov.entries), oct.requests.concat(nov.requests), rail.feed(), household);
  eq(MP.subscriptionStatus(out.ious, "2026-10"), "Netflix 2026-10: Asha paid $5.75 (posted 2026-10-05); Ravi still owes $5.75; Meera still owes $5.74. $11.49 still open.");
  eq(MP.subscriptionStatus(out.ious, "2026-11"), "Netflix 2026-11: Asha still owes $5.75; Ravi still owes $5.75; Meera still owes $5.74. $17.24 still open.");
});
